window.CK_DOSES_CH={"acetylcysteine-iv-paracetamol":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Antidote lors d'intoxication aiguë au paracétamol\nSchéma de posologie intraveineuse selon Prescott\nLe traitement complet avec l'acétylcystéine prévoit 3 perfusions intraveineuses consécutives. Les dosages devraient être administrées sans aucune pause en succession.\nDose totale: 300 mg/kg d'acétylcystéine (correspond à env. 5 flacons de Fluimucil 20 % pour un poids corporel de 70 kg); durée totale 21 heures.\nLe schéma de traitement suivant est recommandé:\n·Peser le patient pour déterminer l'intervalle de poids correct.\n·Utiliser le tableau posologique pour déterminer le volume approprié d'acétylcystéine (volume du flacon) à ajouter à la solution de perfusion pour chacune des 3 phases de perfusion.\n·1 flacon de Fluimucil 20 % contient 25 ml: 5 ml = 1 g d'acétylcystéine. Comme solution de perfusion peuvent être utilisées une solution de glucose à 5 % ou de NaCl à 0,9 %.\nPremière perfusion\nBolus initial de 150 mg/kg dans glucose 5 % ou dans NaCl 0,9 % pendant 60 minutes.\nUn bolus initial plus rapide sur 15-60 minutes peut également être administré, mais l'administration lente du bolus (pendant 60 min.) réduit la probabilité d'apparition de réactions anaphylactoïdes.\nDeuxième perfusion\n50 mg/kg dans glucose 5 % ou dans NaCl 0,9 % pendant 4 heures (= 12,5 mg/kg/h).\nTroisième perfusion\n100 mg/kg dans glucose 5 % ou dans NaCl 0,9 % pendant 16 heures (= 6,25 mg/kg/h).\nPour le calcul de la posologie chez les patients obèses, utiliser un poids limite supérieur de 110 kg.\nCalculer la posologie sur la base du poids réel du patient.\nDéfaillance hépatique aiguë après intoxication au paracétamol\nAussi lors de défaillance hépatique après intoxication au paracétamol, le schéma de traitement selon Prescott est recommandé pendant les 21 premières heures. Ensuite, la dernière perfusion administrée de 150 mg/kg/24 heures doit être poursuivie jusqu'à la disparition de l'encéphalopathie.\nInstructions posologiques particulières\nEnfants/Patients avec un poids corporel inférieur à 40 kg\nLes enfants doivent être traités avec la même posologie des adultes. Cependant, la quantité de solution intraveineuse doit être adaptée sur la base de l'âge et du poids, à cause du danger potentiel d'hypervolémie (fluid overload)."}],"aips_publie":"2022-11-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Novembre 2022)","aips_version":"Novembre 2022","dose":"150 mg/kg en 60 minutes, puis 50 mg/kg en 4 heures, puis 100 mg/kg en 16 heures (300 mg/kg en 21 heures) ; poids plafonné à 110 kg","duree":"21 heures ; en cas de défaillance hépatique, poursuivre 150 mg/kg/24 heures jusqu’à disparition de l’encéphalopathie","id":"acetylcysteine-iv-paracetamol","indication":"antidote de l’intoxication aiguë au paracétamol (schéma de Prescott)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte et enfant (même posologie ; volume adapté chez l’enfant de moins de 40 kg)","produit_ch":"Fluimucil 20 % (Swissmedic 31954)","substance":"acétylcystéine","titulaire":"Zambon Suisse SA, 6814 Cadempino","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=31954&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/511d04f195db4fc8843c8414eea36f14-fr.html","voie":"IV, 3 perfusions sans pause"},"adrenaline-im-adulte-anaphylaxie":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Posologie habituelle\nAdultes\nEpipen\nLa dose habituelle est de 0,3 mg d'adrénaline intramusculaire.\nEnfants et adolescents d'un poids corporel supérieur à 30 kg\nEpipen\nLa dose habituelle est de 0,3 mg d'adrénaline intramusculaire.\nLorsqu'une dose simple est considérée comme insuffisante pour faire régresser les symptômes d'un choc anaphylactique, il est possible d'utiliser deux injecteurs préremplis (2 Epipen ou 1 Epipen et 1 Epipen Junior, voir également «Mises en garde et précautions»).\nIl est également possible de procéder à une seconde administration d'adrénaline avec un nouvel injecteur prérempli Epipen/Epipen Junior 5 à 15 minutes après la première, pour autant que la première dose n'ait pas montré d'effet ou ait montré un effet clinique insuffisant."}],"aips_publie":"2025-09-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Septembre 2025)","aips_version":"Septembre 2025","dose":"0,3 mg","id":"adrenaline-im-adulte-anaphylaxie","indication":"traitement d’urgence de l’anaphylaxie (injecteur prérempli)","intervalle":"seconde injection possible 5 à 15 minutes après la première si l’effet est absent ou insuffisant","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte, et enfant ou adolescent de plus de 30 kg","produit_ch":"Epipen®/Epipen® Junior, solution injectable en injecteur prérempli (Swissmedic 53836)","substance":"adrénaline","titulaire":"Viatris Pharma GmbH, 6312 Steinhausen","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=53836&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/7a7fab518ab34832a7e6d7888ba1bbb3-fr.html","voie":"IM"},"adrenaline-im-enfant-anaphylaxie":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Enfants et adolescents\nLa posologie pédiatrique habituelle est de 0,01 mg/kg de poids corporel.\nNéanmoins, le médecin traitant peut, après un examen soigneux du patient et de la nature de la situation engageant le pronostic vital, prescrire une quantité plus ou moins importante d'adrénaline.\nUne dose inférieure à 0,15 mg ne peut pas être administrée avec Epipen Junior.\nDans le cas où l'injection d'une dose d'adrénaline plus faible se révélerait nécessaire chez un enfant en bas âge, elle doit être administrée d'une autre manière.\nEnfants et adolescents d'un poids corporel supérieur à 30 kg\nEpipen\nLa dose habituelle est de 0,3 mg d'adrénaline intramusculaire.\nEnfants d'un poids corporel compris entre 15 et 30 kg\nEpipen Junior\nLa dose habituelle est de 0,15 mg d'adrénaline intramusculaire.\nEnfants d'un poids corporel compris entre 7,5 et 15 kg\nL'utilisation d'Epipen Junior doit être évaluée au cas par cas chez les enfants dont le poids corporel est compris entre 7,5 et 15 kg.\nEnfants d'un poids corporel inférieur à 7,5 kg\nL'utilisation chez les enfants de moins de 7,5 kg n'est pas recommandée, sauf en cas de danger de mort et sous surveillance médicale.\nLorsqu'une dose simple est considérée comme insuffisante pour faire régresser les symptômes d'un choc anaphylactique, il est possible d'utiliser deux injecteurs préremplis (2 Epipen ou 1 Epipen et 1 Epipen Junior, voir également «Mises en garde et précautions»).\nIl est également possible de procéder à une seconde administration d'adrénaline avec un nouvel injecteur prérempli Epipen/Epipen Junior 5 à 15 minutes après la première, pour autant que la première dose n'ait pas montré d'effet ou ait montré un effet clinique insuffisant."}],"aips_publie":"2025-09-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Septembre 2025)","aips_version":"Septembre 2025","dose":"0,01 mg/kg ; 15 à 30 kg : 0,15 mg (Epipen Junior) ; plus de 30 kg : 0,3 mg","id":"adrenaline-im-enfant-anaphylaxie","indication":"traitement d’urgence de l’anaphylaxie (injecteur prérempli)","intervalle":"seconde injection possible 5 à 15 minutes après la première si l’effet est absent ou insuffisant","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"enfant : 7,5 à 15 kg au cas par cas ; moins de 7,5 kg seulement en cas de danger de mort, sous surveillance médicale","produit_ch":"Epipen®/Epipen® Junior, solution injectable en injecteur prérempli (Swissmedic 53836)","substance":"adrénaline","titulaire":"Viatris Pharma GmbH, 6312 Steinhausen","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=53836&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/7a7fab518ab34832a7e6d7888ba1bbb3-fr.html","voie":"IM"},"adrenaline-iv-adulte-arret-cardiaque":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"L'adrénaline intraveineuse est réservée aux professionnels de santé expérimentés dans l'administration et la titration des vasopresseurs dans le cadre de leur pratique clinique ordinaire.\nRéanimation cardio-pulmonaire\nArrêt cardiaque chez l'adulte\nAdministration de 1 ml de solution d'adrénaline au 1:1'000 (1 mg/ml), par voie intraveineuse ou intraosseuse, répétée toutes les 3 à 5 minutes jusqu'au rétablissement de la circulation spontanée.\nLors de l'arrêt cardiaque, chaque dose de 1 mg d'adrénaline au 1:1'000 (1 mg/ml) administrée par voie veineuse périphérique doit être suivie par un flush d'au moins 20 ml de chlorure de sodium isotonique au moyen d'un raccord en Y afin de faciliter la distribution dans la circulation centrale.\nLa voie endotrachéale ne doit être utilisée qu'en dernier ressort, si aucune autre voie d'administration n'est accessible, à une dose de 2 à 2,5 ml de solution au 1:1'000 (soit l'équivalent de 2 à 2,5 mg).\nPédiatrie\nL'innocuité et l'efficacité d'Adrenalin Aguettant 1 mg/ml chez les enfants et les adolescents n'ont pas été démontrées."}],"aips_publie":"2023-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2023)","aips_version":"Juin 2023","dose":"1 mg (1 ml de solution à 1 mg/ml) ; par la sonde d’intubation, en dernier ressort : 2 à 2,5 mg","id":"adrenaline-iv-adulte-arret-cardiaque","indication":"réanimation cardio-pulmonaire, arrêt cardiaque","intervalle":"toutes les 3 à 5 minutes jusqu’au retour de la circulation spontanée ; rincer chaque dose périphérique par au moins 20 ml de NaCl isotonique","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte (efficacité non démontrée chez l’enfant)","produit_ch":"Adrenalin Aguettant 1 mg/mL (Swissmedic 66396)","substance":"adrénaline","titulaire":"Aguettant Suisse SA","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=66396&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/0cdca8fafe5d45e0b708b514d3a1e497-fr.html","voie":"IV ou voie osseuse"},"alteplase-iv-adulte-avc":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Accident vasculaire cérébral ischémique aigu\nLa dose totale recommandée est de 0,9 mg de principe actif/kg de poids corporel (dose maximale totale: 90 mg) en commençant par 10% de la dose totale en bolus intraveineux initial, suivi immédiatement du reste de la dose totale en perfusion intraveineuse sur 60 minutes.\nLe traitement doit être instauré chez les adultes et les enfants âgés de ≥16 ans (voir «Contre-indications» et «Mises en garde et précautions») dès que possible et au maximum 4,5 heures après le dernier état asymptomatique connu, après exclusion d’une hémorragie intracrânienne au moyen d’une imagerie adéquate.\nL’effet du traitement dépend du temps, ce qui signifie que la probabilité d’une évolution favorable est d’autant plus élevée que le traitement est initié précocement (voir également «Contre-indications» et «Mises en garde et précautions»).\n* Administration selon une concentration de 1 mg/ml en 60 minutes\nActilyse est contre-indiqué pour le traitement de l'accident vasculaire cérébral aigu chez les enfants et les adolescents de moins de 16 ans (voir «Contre-indications»). Pour les adolescents de plus de 16 ans, voir «Mises en garde et précautions»."}],"aips_publie":"2025-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2025)","aips_version":"Juin 2025","dose":"0,9 mg/kg (maximum 90 mg) : 10 % en bolus, puis le reste en perfusion sur 60 minutes","duree":"dès que possible, au plus tard 4,5 heures après le dernier état asymptomatique connu, hémorragie intracrânienne exclue par imagerie","id":"alteplase-iv-adulte-avc","indication":"accident vasculaire cérébral ischémique aigu","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte et adolescent de 16 ans ou plus","produit_ch":"Actilyse® (Swissmedic 48313)","substance":"altéplase","titulaire":"Boehringer Ingelheim (Schweiz) GmbH, Bâle","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=48313&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/6aae41fea9094666bf83bbc10c8c61e8-fr.html","voie":"IV"},"alteplase-iv-adulte-embolie-pulmonaire":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Embolie pulmonaire massive aiguë\nChez les patients avec un poids corporel ≥65 kg:\nAdministrer une dose totale de 100 mg en l'espace de 2 heures. Le schéma posologique le plus souvent utilisé est le suivant:\n·10 mg en bolus intraveineux en 1 à 2 minutes, suivis directement de\n·90 mg en perfusion intraveineuse sur 2 heures jusqu'à atteinte de la dose totale maximale de 100 mg.\nChez les patients avec un poids corporel de < 65 kg:\n·10 mg en bolus intraveineux en 1 à 2 minutes, suivis directement\n·d'une perfusion intraveineuse sur 2 heures jusqu'à la dose totale maximale de 1,5 mg/kg de poids corporel.\nTraitement adjuvant:\nLe traitement par l'héparine doit débuter (ou être poursuivi) après le traitement par Actilyse si les valeurs de l'aPTT sont inférieures à 2 fois les valeurs maximales normales. La perfusion doit être ajustée afin de maintenir un aPTT de 50 à 70 secondes (1,5 à 2,5 fois la valeur de référence)."}],"aips_publie":"2025-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2025)","aips_version":"Juin 2025","dose":"65 kg ou plus : 100 mg en 2 heures (10 mg en bolus en 1 à 2 minutes, puis 90 mg en perfusion sur 2 heures) ; moins de 65 kg : 10 mg en bolus, puis perfusion sur 2 heures jusqu’à 1,5 mg/kg au total","id":"alteplase-iv-adulte-embolie-pulmonaire","indication":"embolie pulmonaire massive aiguë","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Actilyse® (Swissmedic 48313)","substance":"altéplase","titulaire":"Boehringer Ingelheim (Schweiz) GmbH, Bâle","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=48313&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/6aae41fea9094666bf83bbc10c8c61e8-fr.html","voie":"IV"},"alteplase-iv-adulte-infarctus-90-min":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Infarctus aigu du myocarde\na) Schéma posologique sur 90 minutes pour les patients souffrant d'infarctus aigu du myocarde, chez qui le traitement peut commencer dans les 6 heures suivant le début des symptômes:\nChez les patients avec un poids corporel ≥65 kg:\n·15 mg en bolus intraveineux, directement suivis de\n·50 mg en perfusion intraveineuse dans les premières 30 minutes, immédiatement suivis d'une perfusion intraveineuse de\n·35 mg durant 60 minutes, jusqu'à atteinte de la dose maximale de 100 mg au total.\nLa dose totale doit être adaptée selon le schéma suivant chez les patients ayant un poids corporel < 65 kg:\n·15 mg en bolus intraveineux, suivis directement de\n·0,75 mg/kg de poids corporel en perfusion intraveineuse durant les 30 premières minutes (au maximum 50 mg), immédiatement suivis d'une perfusion intraveineuse de\n·0,5 mg/kg de poids corporel durant 60 minutes (jusqu'à 35 mg au maximum).\nTraitement adjuvant:\nUn traitement adjuvant antithrombotique est recommandé conformément aux directives internationales actuelles relatives au traitement de l'infarctus du myocarde avec sus-décalage du segment ST."}],"aips_publie":"2025-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2025)","aips_version":"Juin 2025","dose":"65 kg ou plus : 15 mg en bolus, 50 mg en 30 minutes, puis 35 mg en 60 minutes (100 mg au total) ; moins de 65 kg : 15 mg en bolus, 0,75 mg/kg en 30 minutes (maximum 50 mg), puis 0,5 mg/kg en 60 minutes (maximum 35 mg)","id":"alteplase-iv-adulte-infarctus-90-min","indication":"infarctus aigu du myocarde, traitement possible dans les 6 heures (schéma sur 90 minutes)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Actilyse® (Swissmedic 48313)","substance":"altéplase","titulaire":"Boehringer Ingelheim (Schweiz) GmbH, Bâle","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=48313&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/6aae41fea9094666bf83bbc10c8c61e8-fr.html","voie":"IV"},"amoxicilline-po-adulte":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Après l'obtention d'un effet clinique, il convient de poursuivre le traitement pendant une période de 48 à 72 heures. Lors d'une infection provoquée par streptocoques β-hémolytiques, il est recommandé de poursuivre le traitement pendant au moins dix jours, afin d'éviter la survenue d'un rhumatisme articulaire aigu ou d'une glomérulonéphrite.\nPosologie usuelle\nAdultes et enfants de plus de 40 kg\nInfections légères à moyennes\nConsignes générales: 1500 mg‒3000 mg d'amoxicilline/jour en 3 à 4 doses individuelles.\nPosologie quotidienne maximale: 4000 mg‒6000 mg répartis en 3 à 4 doses.\nPosologie recommandée: 375 à 750 mg 3 à 4 fois par jour.\nL'insuffisance rénale entraîne un ralentissement de l'élimination de l'amoxicilline. Amoxicilline Sandoz peut être dosé en fonction de la clairance de la créatinine (ClCr) selon le schéma suivant:\nAdultes et enfants de plus de 40 kg\nClairance de la créatinine\n(ClCr) (ml/min)\nDose\n10‒30\n500 mg toutes les 12 heures au maximum\n<10\n500 mg toutes les 24 heures au maximum\nLors d'une clairance de la créatinine supérieure à 30 ml/min, aucun ajustement posologique n'est requis."}],"aips_publie":"2024-08-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Août 2024)","aips_version":"Août 2024","dose":"375 à 750 mg 3 à 4 fois par jour (1500 à 3000 mg/j) ; maximum 4000 à 6000 mg/j","duree":"48 à 72 heures après l’effet clinique ; au moins dix jours pour un streptocoque β-hémolytique","id":"amoxicilline-po-adulte","indication":"infections légères à moyennes","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte et enfant de plus de 40 kg ; clairance 10 à 30 ml/min : 500 mg toutes les 12 heures au maximum ; moins de 10 ml/min : 500 mg toutes les 24 heures au maximum","produit_ch":"Amoxicilline Sandoz®, comprimés pelliculés/granulés pour suspension buvable (Swissmedic 49923)","substance":"amoxicilline","titulaire":"Sandoz Pharmaceuticals SA, Risch; domicile: Rotkreuz","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=49923&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/f84f7069b21049fab995c4d7a24e60e5-fr.html","voie":"PO"},"amoxicilline-po-enfant":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Enfants et adolescents\nEnfants jusqu'à 40 kg\nIndications générales: 50‒100 mg/kg/jour, répartis en 3‒4 prises.\nDose journalière maximale: 2000 mg répartis en 3‒4 prises.\nDose unitaire maximale: 50 mg/kg.\nRecommandation posologique\nLes nouveau-nés et prématurés devraient en règle général être traités par voie parentérale, en raison d'une absorption incertaine (transport actif). Traitement oral au plus tôt à partir de 8 jours."}],"aips_publie":"2024-08-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Août 2024)","aips_version":"Août 2024","dose":"50 à 100 mg/kg/j en 3 à 4 prises ; maximum 2000 mg/j ; dose unitaire maximale 50 mg/kg","id":"amoxicilline-po-enfant","indication":"posologie pédiatrique générale","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"enfant jusqu’à 40 kg (nouveau-né : voie parentérale, oral au plus tôt dès 8 jours)","produit_ch":"Amoxicilline Sandoz®, comprimés pelliculés/granulés pour suspension buvable (Swissmedic 49923)","substance":"amoxicilline","titulaire":"Sandoz Pharmaceuticals SA, Risch; domicile: Rotkreuz","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=49923&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/f84f7069b21049fab995c4d7a24e60e5-fr.html","voie":"PO"},"aspirine-po-adulte-cardiovasculaire":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Indications cardiovasculaires sans pontage aorto-coronarien et sans ACTP\n100 mg 1 fois par jour.\nPrévention des thromboses après pontage aorto-coronarien et angioplastie coronarienne transluminale percutanée (ACTP)\n100–300 mg par jour.\nPrévention des accidents cérébro-vasculaires suite à l'apparition de stades précurseurs (AIT)\n100 mg 3 fois par jour ou 300 mg 1 fois par jour.\nIl est recommandé de prendre les comprimés avec un peu de liquide, au moins une demi-heure avant le repas. Boire ensuite ½-1 verre de liquide. En raison de l'enrobage gastro-résistant, les comprimés ne doivent pas être écrasés, coupés ou croqués afin que le principe actif ne soit libéré que dans le milieu alcalin de l'intestin."}],"aips_publie":"2026-03-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Mars 2026)","aips_version":"Mars 2026","dose":"100 mg 1×/j ; après pontage ou angioplastie coronaire : 100 à 300 mg/j ; après AIT : 100 mg 3×/j ou 300 mg 1×/j","id":"aspirine-po-adulte-cardiovasculaire","indication":"indications cardiovasculaires ; après pontage ou angioplastie coronaire ; après AIT","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Aspirine® Cardio 100, Aspirine® Cardio 300 (Swissmedic 51795)","substance":"acide acétylsalicylique","titulaire":"Bayer (Schweiz) AG, 8045 Zurich","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=51795&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/5c0d9caab7df4b4bad5c584cf5bb5fc5-fr.html","voie":"PO"},"aspirine-po-adulte-infarctus":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Infarctus aigu du myocarde\nEn cas d'infarctus aigu du myocarde, 200 à 300 mg d'acide acétylsalicylique par voie intraveineuse ou par voie orale avec une préparation d'acide acétylsalicylique à résorption rapide (forme non gastro-résistante). Les comprimés doivent être avalés sous forme écrasée ou croquée afin d'obtenir une absorption rapide. À partir du deuxième jour, 100 mg d'Aspirine Cardio par jour.\nEn l'absence de données sur l'efficacité et la sécurité chez les enfants et adolescents de moins de 18 ans, Aspirine Cardio ne doit pas être utilisé dans cette population de patients."}],"aips_publie":"2026-03-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Mars 2026)","aips_version":"Mars 2026","dose":"200 à 300 mg (forme à résorption rapide, comprimé écrasé ou croqué), puis 100 mg/j dès le deuxième jour","id":"aspirine-po-adulte-infarctus","indication":"infarctus aigu du myocarde","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte (pas avant 18 ans)","produit_ch":"Aspirine® Cardio 100, Aspirine® Cardio 300 (Swissmedic 51795)","substance":"acide acétylsalicylique","titulaire":"Bayer (Schweiz) AG, 8045 Zurich","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=51795&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/5c0d9caab7df4b4bad5c584cf5bb5fc5-fr.html","voie":"IV ou PO"},"atropine-iv-adulte-bradycardie":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Phase aiguë des troubles du rythme cardiaque avec bradycardie\nChez l'adulte: 0,5–1,0 (–1,5) mg i.v., à répéter éventuellement après 3–5 minutes. Dans les cas de bradycardie sévère, la dose totale administrée ne devrait pas dépasser 3 mg (0,04 mg/kg). Si nécessaire, répéter toutes les 4–6 heures s.c. ou i.v.\nEn raison du risque d'apparition d'une baisse paradoxale de la fréquence cardiaque lors de faibles doses ou d'une administration très lente, il convient de ne pas administrer des doses de sulfate d'atropine en dessous de 0,5 mg lors d'états bradycardiques."}],"aips_publie":"2025-01-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Janvier 2025)","aips_version":"Janvier 2025","dose":"0,5 à 1,0 (jusqu’à 1,5) mg ; pas moins de 0,5 mg ; total maximal 3 mg (0,04 mg/kg)","id":"atropine-iv-adulte-bradycardie","indication":"phase aiguë des troubles du rythme avec bradycardie","intervalle":"répéter éventuellement après 3 à 5 minutes","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Atropinum Sulf. Sintetica 0,5 mg/ml, 1mg/ml (Swissmedic 56533)","substance":"atropine","titulaire":"Sintetica SA, 6850 Mendrisio","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=56533&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/fcc3253cab574b47b000d7eac2d710e1-fr.html","voie":"IV"},"atropine-iv-adulte-organophosphores":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Intoxication avec des esters organophosphorés\nAdultes: les recommandations posologiques varient considérablement selon les références.\nLa majorité des doses initiales recommandées se situent entre 1 et 6 mg i.v. (commentaire DAB 10, 1991: initialement 2,5 mg i.v.; AHFS 97: initialement 1–2 mg i.v. [cas graves 2–6 mg]).\nUne répétition doit être effectuée toutes les 5 à 60 minutes avec une dose de 1–2 mg i.v.\nEnfants: 0,05 mg/kg i.m. ou i.v. à répéter toutes les 10–30 minutes. La posologie dépend des symptômes (dilatation pupillaire, sécrétion bronchique)."}],"aips_publie":"2025-01-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Janvier 2025)","aips_version":"Janvier 2025","dose":"1 à 6 mg initialement (recommandations variables), puis 1 à 2 mg ; enfant : 0,05 mg/kg toutes les 10 à 30 minutes","id":"atropine-iv-adulte-organophosphores","indication":"intoxication aux esters organophosphorés","intervalle":"toutes les 5 à 60 minutes, selon les signes (pupilles, sécrétions bronchiques)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte ; enfant","produit_ch":"Atropinum Sulf. Sintetica 0,5 mg/ml, 1mg/ml (Swissmedic 56533)","substance":"atropine","titulaire":"Sintetica SA, 6850 Mendrisio","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=56533&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/fcc3253cab574b47b000d7eac2d710e1-fr.html","voie":"IV (enfant : IM ou IV)"},"azithromycine-po-adulte":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Zithromax doit être administré une fois par jour.\nPosologie usuelle\nAdultes\nDans toutes les indications sauf les infections à Chlamydia trachomatis et la prophylaxie des infections à MAC\nLa dose totale s'élève à 1'500 mg et doit être répartie comme suit: Jour 1 à jour 3: 500 mg/jour (1 comprimé pelliculé à 500 mg ou 2 comprimés pelliculés à 250 mg).\nInfections à Chlamydia trachomatis\nLes maladies sexuellement transmissibles dues à Chlamydia trachomatis sont traitées par une dose unique de 1'000 mg d'azithromycine par voie orale (2 comprimés pelliculés à 500 mg ou 4 comprimés pelliculés à 250 mg)."}],"aips_publie":"2023-03-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Mars 2023)","aips_version":"Mars 2023","dose":"500 mg 1×/j pendant 3 jours (1500 mg au total) ; Chlamydia trachomatis : 1000 mg en dose unique","id":"azithromycine-po-adulte","indication":"toutes indications sauf Chlamydia trachomatis et prophylaxie MAC ; Chlamydia trachomatis","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Zithromax®, Comprimés pelliculés et poudre pour suspension buvable (Swissmedic 51352)","substance":"azithromycine","titulaire":"Pfizer AG, Zürich","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=51352&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/b7e790d2f71c4596804da27243270fe1-fr.html","voie":"PO"},"azithromycine-po-enfant":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Enfants et adolescents\nDans toutes les indications sauf la prévention des infections à MAC\nLa dose totale chez l'enfant de plus de 6 mois est de 30 mg/kg de poids corporel (PC). Administrer une dose quotidienne unique de 10 mg/kg PC pendant 3 jours.\nUtiliser de préférence Zithromax en suspension ou azithromycine en sachets pour traiter les enfants dont le poids corporel est inférieur à 45 kg. Aucune donnée n'existe sur les enfants de moins de 6 mois."}],"aips_publie":"2023-03-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Mars 2023)","aips_version":"Mars 2023","dose":"10 mg/kg une fois par jour pendant 3 jours (30 mg/kg au total)","id":"azithromycine-po-enfant","indication":"toutes indications sauf prophylaxie MAC","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"enfant de plus de 6 mois","produit_ch":"Zithromax®, Comprimés pelliculés et poudre pour suspension buvable (Swissmedic 51352)","substance":"azithromycine","titulaire":"Pfizer AG, Zürich","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=51352&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/b7e790d2f71c4596804da27243270fe1-fr.html","voie":"PO"},"ceftriaxone-adulte-lyme":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Pour l'administration intramusculaire (i.m.), un solvant à base de lidocaïne est utilisé. D'éventuelles contre-indications à la lidocaïne doivent par conséquent être exclues avant toute injection i.m. de ceftriaxone (voir «Contre-indications»).\nMaladie de Lyme\nLa posologie en cas de maladie de Lyme est de 50 mg par kg, 2 g au maximum, chez l'enfant et l'adulte, administrés une fois par jour pendant 14 jours."}],"aips_publie":"2025-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2025)","aips_version":"Juin 2025","dose":"50 mg/kg, maximum 2 g","duree":"14 jours","id":"ceftriaxone-adulte-lyme","indication":"maladie de Lyme","intervalle":"une fois par jour","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"enfant et adulte","produit_ch":"Rocephin® (Swissmedic 44625)","substance":"ceftriaxone","titulaire":"Roche Pharma (Suisse) SA, Bâle","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=44625&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/8d9346c377864ce8a9b0034d146e9b2f-fr.html","voie":"IV ou IM"},"ceftriaxone-iv-adulte":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Pour l'administration intramusculaire (i.m.), un solvant à base de lidocaïne est utilisé. D'éventuelles contre-indications à la lidocaïne doivent par conséquent être exclues avant toute injection i.m. de ceftriaxone (voir «Contre-indications»).\nPosologie\nAdultes et enfants de plus de douze ans\nEn général, 1 - 2 g de Rocephin une fois par jour (toutes les 24 heures). Lors d'infections sévères ou en présence de germes moyennement sensibles, la dose quotidienne unique peut être augmentée jusqu'à 4 g.\nChez les enfants d'un poids corporel de 50 kg ou plus, il faut avoir recours à la posologie usuelle pour adultes.\nAucun ajustement posologique n'est nécessaire à condition que la fonction hépatique ne soit pas altérée. Ce n'est que dans les cas d'insuffisance rénale préterminale (clairance de la créatinine < 10 ml/min) que la dose quotidienne de Rocephin ne doit pas dépasser 2 g.\nLa ceftriaxone n'est pas éliminée par dialyse péritonéale ou hémodialyse. Chez les patients dialysés, aucune administration supplémentaire n'est donc nécessaire à l'issue de la dialyse. Ne pas dépasser 2 g/jour chez les dialysés."}],"aips_publie":"2025-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2025)","aips_version":"Juin 2025","dose":"1 à 2 g ; jusqu’à 4 g en cas d’infection sévère ou de germe moyennement sensible","id":"ceftriaxone-iv-adulte","indication":"posologie générale","intervalle":"1×/j (toutes les 24 heures)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte et enfant de plus de douze ans (et enfant de 50 kg ou plus) ; insuffisance rénale préterminale ou dialyse : maximum 2 g/j","produit_ch":"Rocephin® (Swissmedic 44625)","substance":"ceftriaxone","titulaire":"Roche Pharma (Suisse) SA, Bâle","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=44625&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/8d9346c377864ce8a9b0034d146e9b2f-fr.html","voie":"IV ou IM"},"ceftriaxone-iv-enfant-meningite":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Rocephin est contre-indiqué chez les prématurés jusqu'à un âge post-menstruel de 41 semaines (âge gestationnel + âge postnatal) (voir «Contre-indications»).\nL'administration intraveineuse de doses égales ou supérieures à 50 mg par kg de poids corporel chez les nourrissons et les enfants jusqu'à 12 ans doit avoir lieu par perfusion d'une durée minimale de 30 minutes. Chez les nouveau-nés, les doses intraveineuses doivent être administrées sur une durée de 60 minutes afin de diminuer le risque potentiel d'encéphalopathie bilirubinique.\nMéningite\nEn cas de méningite bactérienne chez l'enfant en bas âge et l'enfant, le traitement est instauré à raison de 100 mg/kg (pas plus de 4 g) une fois par jour. Dès que le germe a été identifié et que sa sensibilité a été déterminée, la posologie peut être réduite en conséquence. Les meilleurs résultats ont été obtenus avec les durées de traitement suivantes:\nNeisseria meningitidis\n4 jours\nHaemophilus influenzae\n6 jours\nStreptococcus pneumoniae\n7 jours"}],"aips_publie":"2025-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2025)","aips_version":"Juin 2025","dose":"100 mg/kg (maximum 4 g)","duree":"méningocoque 4 jours ; Haemophilus influenzae 6 jours ; pneumocoque 7 jours ; perfusion d’au moins 30 minutes dès 50 mg/kg","id":"ceftriaxone-iv-enfant-meningite","indication":"méningite bactérienne de l’enfant","intervalle":"une fois par jour","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"nourrisson et enfant jusqu’à 12 ans (contre-indiquée chez le prématuré jusqu’à 41 semaines post-menstruelles)","produit_ch":"Rocephin® (Swissmedic 44625)","substance":"ceftriaxone","titulaire":"Roche Pharma (Suisse) SA, Bâle","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=44625&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/8d9346c377864ce8a9b0034d146e9b2f-fr.html","voie":"IV"},"enoxaparine-adulte-stemi":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Traitement de l'infarctus du myocarde aigu avec élévation du segment ST (STEMI)\nLa dose recommandée est de 30 mg d'énoxaparine en un seul bolus IV plus une dose de 1 mg/kg SC, puis une injection de 1 mg/kg SC toutes les 12 heures (maximum 100 mg pour chacune des 2 premières doses sous-cutanées, puis 1 mg/kg pour les doses sous-cutanées suivantes). Pour les patients âgés de 75 ans ou plus, voir la section «Posologie spéciale, patients âgés».\nL'énoxaparine administrée conjointement avec un thrombolytique (spécifique ou non de la fibrine) devrait être donnée entre 15 minutes avant et 30 minutes après le début de la thérapie fibrinolytique. Tous les patients devraient recevoir de l'acide acétylsalicylique dès que le diagnostic STEMI est posé. Sauf contre-indication, ce traitement doit être poursuivi à une dose comprise entre 75 et 325 mg une fois par jour.\nIl est recommandé d'administrer l'énoxaparine jusqu'à la sortie de l'hôpital ou durant un maximum de 8 jours.\nPatients âgés\n• Pour le traitement de l'infarctus du myocarde aigu avec élévation du segment ST (STEMI):\nChez les patients âgés de 75 ans ou plus, ne pas donner de bolus IV initial. Administrer 0,75 mg/kg SC toutes les 12 heures (maximum 75 mg pour chacune des 2 premières doses sous-cutanées, puis 0,75 mg/kg pour les doses sous-cutanées restantes)."}],"aips_publie":"2026-02-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Février 2026)","aips_version":"Février 2026","dose":"30 mg en bolus IV + 1 mg/kg SC, puis 1 mg/kg SC toutes les 12 heures (maximum 100 mg pour les 2 premières doses SC) ; 75 ans ou plus : pas de bolus, 0,75 mg/kg SC toutes les 12 heures (maximum 75 mg pour les 2 premières doses)","duree":"jusqu’à la sortie, au maximum 8 jours","id":"enoxaparine-adulte-stemi","indication":"infarctus aigu du myocarde avec sus-décalage ST (STEMI)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Clexane®/- multi (Swissmedic 49456)","substance":"énoxaparine","titulaire":"sanofi-aventis (suisse) sa, 1214 Vernier/GE","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=49456&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/3b42abe606a74cccbcbd45f823b104f3-fr.html","voie":"IV puis SC"},"enoxaparine-sc-adulte-angor-instable":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Traitement de l'angine de poitrine instable et de l'infarctus du myocarde sans onde Q\nLa posologie recommandée d'énoxaparine est de 1 mg/kg SC, toutes les 12 heures, en association avec l'administration orale d'acide acétylsalicylique (de 100 à 325 mg, une fois par jour).\nLe traitement de ces patients avec l'énoxaparine doit être prescrit pour 2 jours au minimum et se poursuivre jusqu'à la stabilisation clinique. La durée usuelle du traitement s'étend de 2 à 8 jours."}],"aips_publie":"2026-02-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Février 2026)","aips_version":"Février 2026","dose":"1 mg/kg toutes les 12 heures, avec acide acétylsalicylique 100 à 325 mg 1×/j","duree":"au moins 2 jours, en général 2 à 8 jours","id":"enoxaparine-sc-adulte-angor-instable","indication":"angor instable et infarctus sans onde Q","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Clexane®/- multi (Swissmedic 49456)","substance":"énoxaparine","titulaire":"sanofi-aventis (suisse) sa, 1214 Vernier/GE","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=49456&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/3b42abe606a74cccbcbd45f823b104f3-fr.html","voie":"SC"},"enoxaparine-sc-adulte-prophylaxie":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Chez les patients présentant un risque thromboembolique modéré, la prévention efficace de la maladie thrombo-embolique est obtenue par une injection quotidienne d'une dose de 20 mg (0,2 ml = 2000 U.I. anti-Xa) sous-cutanée (SC). En chirurgie générale, la première injection sera effectuée environ deux heures avant l'intervention.\nChez les patients à haut risque thrombo-embolique, en particulier dans le cadre de la chirurgie orthopédique et oncologique dans la région abdominale et pelvienne, la posologie d'énoxaparine sera de 40 mg (0,4 ml = 4000 U.I. anti-Xa) SC, à raison d'une injection quotidienne. En chirurgie orthopédique et oncologique dans les régions abdominale et pelvienne, la première injection sera pratiquée 12 heures avant l'intervention.\nLa durée du traitement coïncidera avec celle de la persistance du risque thrombo-embolique, en général jusqu'à déambulation du patient (en moyenne 7 à 10 jours après l'intervention). En chirurgie orthopédique un traitement prolongé de la prophylaxie avec 40 mg SC 1×/jour pendant 3 semaines en plus du traitement initial a été démontrée comme efficace. Une thromboprophylaxie prolongée (4 semaines) est recommandée pour les procédures oncologiques dans la région abdominale et pelvienne, sans risque accru d'hémorragie grave (basé sur la littérature et les directives). Lorsqu'un traitement anticoagulant à long terme est prévu, on devrait passer à temps à un traitement anticoagulant oral.\nProphylaxie de thrombose veineuse dans la médecine générale\nLa posologie recommandée d'énoxaparine est de 40 mg, à raison d'une injection quotidienne par voie sous-cutanée. Le traitement est maintenu pendant 6 jours au minimum et il doit être poursuivi jusqu'à la mobilisation complète du malade, au maximum 14 jours.\nUne surveillance soigneuse est indiquée en cas d'insuffisance rénale faible à modérée (clairance de la créatinine comprise entre 30 et 80 ml/min). Un ajustement posologique est nécessaire en cas d'insuffisance rénale sévère (clairance de la créatinine < 30 ml/min), en raison de l'exposition à l'énoxaparine significativement plus élevée:\nDoses prophylactiques\nPosologie usuelle\nInsuffisance rénale sévère\n40 mg sous-cutanée 1× par jour\n20 mg sous-cutanée 1× par jour\n20 mg sous-cutanée 1× par jour"}],"aips_publie":"2026-02-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Février 2026)","aips_version":"Février 2026","dose":"40 mg 1×/j (risque modéré en chirurgie : 20 mg 1×/j) ; clairance < 30 ml/min : 20 mg 1×/j","duree":"médecine : au moins 6 jours, au maximum 14 jours ; chirurgie : en moyenne 7 à 10 jours","id":"enoxaparine-sc-adulte-prophylaxie","indication":"prophylaxie de la thrombose veineuse (chirurgie à haut risque ; médecine)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Clexane®/- multi (Swissmedic 49456)","substance":"énoxaparine","titulaire":"sanofi-aventis (suisse) sa, 1214 Vernier/GE","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=49456&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/3b42abe606a74cccbcbd45f823b104f3-fr.html","voie":"SC"},"enoxaparine-sc-adulte-tvp-ep":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Traitement de la thrombose veineuse profonde avec ou sans embolie pulmonaire\nL'énoxaparine s'administre par voie sous cutanée, en deux injections par jour de 1 mg/kg de poids corporel. Alternativement et seulement chez les patients sans problèmes thromboemboliques compliqués l'administration d'une seule injection par jour de 1,5 mg/kg de poids corporel est possible. Chez les patients avec des problèmes thromboemboliques compliqués, il est recommandé d'injecter une dose de 1 mg/kg de poids corporel deux fois par jour.\nChez les patients obèses ou souffrants d'un cancer, il a été montré que l'efficacité est diminuée lors de l'injection d'une seule dose par jour de 1,5 mg/kg de poids corporel d'énoxaparine. Par conséquent, il est recommandé d'administrer l'énoxaparine en deux injections de 1 mg/kg par jour chez ces patients.\nEn moyenne, le traitement initial à l'énoxaparine dure environ 10 jours. L'introduction d'un traitement anticoagulant par voie orale (antagonistes de la vitamine K) se superposera au traitement par l'énoxaparine, qui sera poursuivi jusqu'à ce que le temps de thromboplastine se situe dans le domaine thérapeutique désiré.\nUne surveillance soigneuse est indiquée en cas d'insuffisance rénale faible à modérée (clairance de la créatinine comprise entre 30 et 80 ml/min). Un ajustement posologique est nécessaire en cas d'insuffisance rénale sévère (clairance de la créatinine < 30 ml/min), en raison de l'exposition à l'énoxaparine significativement plus élevée:\nDoses thérapeutiques\nPosologie usuelle\nInsuffisance rénale sévère\n1 mg/kg SC 2× par jour, alternativement 1,5 mg/kg 1× par jour (voir plus haut)\n1 mg/kg SC 1× par jour"}],"aips_publie":"2026-02-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Février 2026)","aips_version":"Février 2026","dose":"1 mg/kg 2×/j ; ou 1,5 mg/kg 1×/j sans problème thromboembolique compliqué ; clairance < 30 ml/min : 1 mg/kg 1×/j","duree":"environ 10 jours en moyenne, relais par anticoagulant oral qui chevauche","id":"enoxaparine-sc-adulte-tvp-ep","indication":"thrombose veineuse profonde avec ou sans embolie pulmonaire","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte (obésité ou cancer : 1 mg/kg 2×/j)","produit_ch":"Clexane®/- multi (Swissmedic 49456)","substance":"énoxaparine","titulaire":"sanofi-aventis (suisse) sa, 1214 Vernier/GE","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=49456&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/3b42abe606a74cccbcbd45f823b104f3-fr.html","voie":"SC"},"glucagon-im-hypoglycemie-severe":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Hypoglycémies sévères\nPosologie chez les adultes\nInjectez 1 mg par voie sous-cutanée ou intramusculaire. Traitement ultérieur: voir la description ci-après.\nPosologie chez les enfants\nInjectez 1 mg (enfants de plus de 25 kg ou de plus de 6 à 8 ans) ou 0,5 mg (enfants de moins de 25 kg ou de moins de 6 à 8 ans), par voie sous-cutanée ou intramusculaire. Traitement ultérieur, voir la description ci-après.\na) Administration par le personnel médical\nAdministration: par voie sous-cutanée ou intramusculaire. Le patient réagit normalement dans les 10 minutes qui suivent l'injection.\nSi le patient a réagi au traitement, lui administrer des hydrates de carbone par voie orale afin de reconstituer les réserves hépatiques de glycogène et de prévenir une récidive d'hypoglycémie.\nSi le patient ne réagit pas à l'injection dans les 10 minutes qui suivent, injecter du glucose par voie intraveineuse."}],"aips_publie":"2021-11-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Novembre 2021)","aips_version":"Novembre 2021","dose":"adulte : 1 mg ; enfant de plus de 25 kg ou de plus de 6 à 8 ans : 1 mg ; enfant plus petit : 0,5 mg","id":"glucagon-im-hypoglycemie-severe","indication":"hypoglycémie sévère","intervalle":"sans réponse dans les 10 minutes : glucose IV ; après réponse : glucides par voie orale","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte et enfant","produit_ch":"GlucaGen® Novo Nordisk (Swissmedic 31489)","substance":"glucagon","titulaire":"Novo Nordisk Pharma AG, Kloten","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=31489&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/62a969113bb94424a0c393d058092c65-fr.html","voie":"SC ou IM"},"heparine-iv-adulte-sca":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Traitement de l'angine de poitrine instable ou de l'infarctus du myocarde sans élévation du segment ST:\nBolus\nDose d'entretien\n60-70 U.I./kg PC (dose maximale: 5 000 U.I.), par voie intraveineuse\n12-15 U.I./kg PC par heure (maximum 1 000 U.I. par heure), par perfusion intraveineuse\nTraitement de l'infarctus du myocarde avec élévation du segment ST associé à des fibrinolytiques (voir rubrique «Interactions»):\nBolus\nDose d'entretien\n60 U.I./kg PC (maximum 4 000 U.I.), par voie intraveineuse\n12 U.I./kg PC par heure (maximum 1 000 U.I. par heure) par perfusion intraveineuse"}],"aips_publie":"2026-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2026)","aips_version":"Juin 2026","dose":"angor instable ou NSTEMI : 60 à 70 UI/kg (maximum 5000 UI), puis 12 à 15 UI/kg/heure (maximum 1000 UI/heure) ; STEMI sous fibrinolytique : 60 UI/kg (maximum 4000 UI), puis 12 UI/kg/heure (maximum 1000 UI/heure)","id":"heparine-iv-adulte-sca","indication":"angor instable ou infarctus sans sus-décalage ST ; infarctus avec sus-décalage ST sous fibrinolytique","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Heparin-Na 25 000 U.I./5 mL B. Braun (Swissmedic 46613)","substance":"héparine non fractionnée","titulaire":"B. Braun Medical AG, Sempach","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=46613&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/4f8f734c6a0a4c9bb6ef48c2446fe431-fr.html","voie":"IV, puis perfusion IV"},"heparine-iv-adulte-thromboembolie":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Posologies recommandées\nTraitement des maladies thromboemboliques veineuses et artérielles (y compris traitement précoce de l'infarctus du myocarde et de l'angine de poitrine instable):\nL'ajustement de la posologie thérapeutique doit s'effectuer sur la base d'examens réguliers du temps de thromboplastine partielle (aPTT, activated Partial Thromboplastin Time), voir rubrique «Mises en garde et précautions».\nAdultes\nBolus\nDose d'entretien\n80 U.I./kg PC, par voie intraveineuse\n18 U.I./kg PC par heure, par perfusion intraveineuse"}],"aips_publie":"2026-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2026)","aips_version":"Juin 2026","dose":"80 UI/kg en bolus, puis 18 UI/kg/heure","id":"heparine-iv-adulte-thromboembolie","indication":"traitement des maladies thromboemboliques veineuses et artérielles","intervalle":"ajustement sur l’aPTT","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Heparin-Na 25 000 U.I./5 mL B. Braun (Swissmedic 46613)","substance":"héparine non fractionnée","titulaire":"B. Braun Medical AG, Sempach","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=46613&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/4f8f734c6a0a4c9bb6ef48c2446fe431-fr.html","voie":"IV, puis perfusion IV"},"heparine-sc-adulte-prophylaxie":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Prophylaxie thromboembolique\nAdultes\n5 000 U.I. toutes les 8 à 12 heures par voie sous-cutanée, en général pendant au moins 5 jours ou jusqu'à la sortie de l'hôpital, si celle-ci intervient avant.\nChez les patients qui subissent une intervention chirurgicale, la première dose doit être administrée 2 heures avant l'opération; la prophylaxie thrombotique doit être poursuivie pendant 2 à 3 semaines après l'intervention chirurgicale."}],"aips_publie":"2026-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2026)","aips_version":"Juin 2026","dose":"5000 UI","duree":"au moins 5 jours ou jusqu’à la sortie ; chirurgie : première dose 2 heures avant, puis 2 à 3 semaines","id":"heparine-sc-adulte-prophylaxie","indication":"prophylaxie thromboembolique","intervalle":"toutes les 8 à 12 heures","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte","produit_ch":"Heparin-Na 25 000 U.I./5 mL B. Braun (Swissmedic 46613)","substance":"héparine non fractionnée","titulaire":"B. Braun Medical AG, Sempach","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=46613&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/4f8f734c6a0a4c9bb6ef48c2446fe431-fr.html","voie":"SC"},"hydroxychloroquine-po-adulte-lupus":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Prendre les comprimés de préférence pendant les repas et en buvant abondamment.\nPosologie usuelle\nLupus érythémateux\nDose initiale, 1 comprimé pelliculé 2-3 fois par jour (= 400-600 mg par jour). Si une rémission se produit après quelques semaines, la posologie quotidienne sera alors ramenée à 1 comprimé pelliculé 1-2 fois par jour, soit 200-400 mg par jour.\nEnfants et adolescents\nEnfants > 6 ans (> 35 kg)\nOn préconise une dose quotidienne de 5-7 mg/kg de poids corporel dans les indications suivantes:\nPolyarthrite chronique évolutive\nLupus érythémateux\nPhotodermatoses\nCe médicament ne doit pas être administré aux enfants âgés de moins de 6 ans et/ou ayant un poids corporel en dessous de 35 kg car les comprimés pelliculés de 200 mg ne sont pas adaptés."}],"aips_publie":"2025-02-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Février 2025)","aips_version":"Février 2025","dose":"400 à 600 mg/j (1 comprimé de 200 mg 2 à 3 fois par jour), puis 200 à 400 mg/j après rémission","id":"hydroxychloroquine-po-adulte-lupus","indication":"lupus érythémateux","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte ; enfant de plus de 6 ans et de plus de 35 kg : 5 à 7 mg/kg/j","produit_ch":"Plaquenil® (Swissmedic 53831)","substance":"hydroxychloroquine","titulaire":"sanofi-aventis (suisse) sa, 1214 Vernier/GE","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=53831&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/db7dc4e5c80e40938d0ead78720aa577-fr.html","voie":"PO"},"lorazepam-iv-adulte-anxiete-aigue":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Psychiatrie\nDans des états anxieux aigus avec ou sans excitation psychomotrice (et dépendant de leur cause, de leur gravité, ainsi que du poids corporel du patient), administrer comme dose initiale 0.05 mg par kg de poids corporel par voie i.v. ou 2-4 mg.\nAprès régression des symptômes aigus, le traitement peut être poursuivi en administrant Lorazepam oral. Le potentiel de dépendance doit alors être pris en compte (voir «Mises en garde et précautions, dépendance»).\nRemarque: il faut toujours tenir compte du fait qu'une injection i.v. risque de provoquer un arrêt respiratoire; de même, une forte sédation peut entraîner une obstruction respiratoire partielle. Des appareils de réanimation doivent donc toujours être à portée de main.\nPour les patients âgés ou affaiblis, on recommande une diminution d'environ 50% de la dose initiale. La posologie peut ensuite être adaptée en fonction de la réponse et de la tolérance de chaque patient.\nChez les patients plus âgés (plus de 50 ans), une injection i.v. peut provoquer une sédation plus marquée et plus longue. Une dose de 2 mg ne doit donc en principe pas être dépassée.\nEnfants et adolescents\nPour les enfants et adolescents de moins de 18 ans voir «Contre-indications»."}],"aips_publie":"2020-11-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Novembre 2020)","aips_version":"Novembre 2020","dose":"0,05 mg/kg ou 2 à 4 mg (dose initiale) ; plus de 50 ans : en principe pas plus de 2 mg","id":"lorazepam-iv-adulte-anxiete-aigue","indication":"état anxieux aigu, avec ou sans excitation psychomotrice (pas d’indication pour l’état de mal épileptique dans ce texte)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte ; patient âgé ou affaibli : environ 50 % de la dose initiale ; moins de 18 ans : voir Contre-indications","produit_ch":"Lorazepam Xilmac®, solution injectable (Swissmedic 50490)","substance":"lorazépam","titulaire":"Leman SKL SA ; Lancy","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=50490&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/843808ac8a4e43de8b57b0e38cfd3317-fr.html","voie":"IV lente"},"lorazepam-po-adulte":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Posologie usuelle\n1 mg de lorazépam 2-3 fois par jour selon l'importance des symptômes, la durée du traitement et les besoins individuels.\nEn cas de troubles du sommeil, généralement 1 mg de lorazépam une demi-heure avant le coucher.\nEn psychiatrie\n3-7.5 mg de lorazépam par jour, répartis en 3-4 prises.\nDurée du traitement\nLa durée du traitement doit être aussi brève que possible et ne doit généralement pas dépasser 2-3 mois. En cas de traitement de longue durée, évaluer régulièrement la nécessité de poursuivre le traitement.\nLe traitement par Temesta, comprimés ou Temesta Expidet, lyophilisat oral ne doit pas être interrompu brusquement en raison de possibles symptômes de sevrage; réduire progressivement la posologie.\nPatients âgés ou affaiblis\nPour les patients âgés ou affaiblis, on recommande une diminution d'environ 50% de la dose initiale. La posologie peut ensuite être adaptée en fonction de la réponse et de la tolérance de chaque patient."}],"aips_publie":"2022-11-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Novembre 2022)","aips_version":"Novembre 2022","dose":"1 mg 2 à 3 fois par jour ; sommeil : 1 mg une demi-heure avant le coucher ; psychiatrie : 3 à 7,5 mg/j en 3 à 4 prises","duree":"aussi brève que possible, en général pas plus de 2 à 3 mois ; arrêt progressif","id":"lorazepam-po-adulte","indication":"posologie usuelle (anxiété, troubles du sommeil, psychiatrie)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte ; patient âgé ou affaibli : environ 50 % de la dose initiale","produit_ch":"Temesta®/Temesta Expidet® (Swissmedic 36203)","substance":"lorazépam","titulaire":"Pfizer AG, Zürich","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=36203&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/b4525d82676b4c3f9025743510eed542-fr.html","voie":"PO"},"naloxone-iv-adulte-surdosage-opioide":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"2. Surdosage d’opioïdes connu ou suspecté\nAdultes\nLa posologie initiale habituelle est de 0.4 à 2 mg de chlorhydrate de naloxone par voie i.v., i.m. ou s.c.\nSi l’effet antagoniste et l’amélioration souhaités de la fonction respiratoire ne sont pas obtenus immédiatement après la première injection i.v., l’injection peut être répétée à des intervalles de 2 à 3 minutes par voie intraveineuse. Si une deuxième ou troisième injection reste sans effet, on peut en conclure que l’état du patient doit être rapporté, en partie ou en totalité, à une autre pathologie ou à des substances de type non opioïde. Si aucune amélioration notable n’est observée après administration de 10 mg de chlorhydrate de naloxone, la dépression respiratoire n’est pas due à un opioïde. Exceptions: la buprénorphine et des doses élevées d’opioïdes à effet agoniste-antagoniste.\nEnfants et adolescents\nNaloxon OrPha doit être dilué avant administration (voir «Remarques particulières», «Instructions pour la manipulation»).\nLa posologie initiale habituelle de chlorhydrate de naloxone est de 0.01 mg/kg de poids corporel par voie i.v. Si cette dose n’entraîne pas l’amélioration souhaitée de l’état clinique, des doses supplémentaires de 0.01 mg/kg chacune peuvent être administrées à intervalles de 2 à 3 minutes. Si l’application intraveineuse n’est pas praticable, Naloxon OrPha peut être donné par voie i.m. ou s.c. en doses fractionnées.\nMode d’administration\nNaloxon OrPha peut être administré par voie i.v., i.m. ou s.c. L’effet intervient le plus rapidement après administration i.v.; en cas d’urgence, il est donc conseillé d’administrer Naloxon OrPha par voie i.v. Après injection i.m., l’effet est moins rapide, mais se maintient plus longtemps. La voie i.m. ne devrait être choisie que si une administration par voie i.v. n’est pas possible. Le début et la durée de l’effet sont fonction de la dose et du mode d’administration.\nLa durée de l’effet de certains opioïdes dépassant celle du chlorhydrate de naloxone, il est indiqué de maintenir le patient sous surveillance étroite, même s’il réagit d’abord de façon satisfaisante à la naloxone, car une nouvelle injection de chlorhydrate de naloxone peut s’avérer nécessaire."}],"aips_publie":"2026-07-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juillet 2026)","aips_version":"Juillet 2026","dose":"0,4 à 2 mg ; enfant : 0,01 mg/kg","id":"naloxone-iv-adulte-surdosage-opioide","indication":"surdosage d’opioïdes connu ou suspecté","intervalle":"répéter toutes les 2 à 3 minutes ; sans amélioration après 10 mg, la dépression respiratoire n’est pas due à un opioïde","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte ; enfant et adolescent : 0,01 mg/kg, répété toutes les 2 à 3 minutes","produit_ch":"Naloxon OrPha (Swissmedic 56952)","substance":"naloxone","titulaire":"OrPha Swiss GmbH, 8700 Küsnacht","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=56952&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/af2b533874254aabbba66ae2d2d00008-fr.html","voie":"IV, IM ou SC (IV en urgence)"},"noradrenaline-iv-adulte-perfusion":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"La plus petite dose efficace de noradrénaline devrait être administrée pendant le temps nécessaire le plus court possible.\nAdultes: La vitesse initiale de la perfusion à un poids de 70 kg doit être comprise entre 8 et 12 µg/minute.\nAlternative: Une fois la perfusion de noradrénaline établie, la dose doit être titrée par paliers de 0,05 à 0,1 µg/kg/minute de noradrénaline base avec titration croissante jusqu’à obtention de la dose efficace. Il existe une forte variation individuelle de la posologie nécessaire pour atteindre et maintenir une tension normale. L’objectif doit être d’établir une pression artérielle systolique normale faible (100-120 mmHg) ou d’atteindre une pression artérielle moyenne adéquate (> 65 à 80 mm Hg – en fonction de l’état du patient).\nLa dose d’entretien moyenne est de 2 à 4 µg/minute.\nLa dose peut aller jusqu’à 30 µg/minute chez les patients avec un choc réfractaire.\nEnfants: l’utilisation chez l’enfant n’est pas recommandée.\nLa pression sanguine doit être contrôlée toutes les 2 minutes jusqu’à atteindre la valeur souhaitée, puis toutes les 5 minutes pendant toute la durée de la perfusion. La pression sanguine doit être réglée jusqu’à une valeur à peine inférieure à la pression normale du patient. Eviter tout arrêt immédiat de l’administration de noradrénaline.\nLa perfusion doit être réalisée au moyen d’un cathéter veineux."}],"aips_publie":"2020-10-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Octobre 2020)","aips_version":"Octobre 2020","dose":"débit initial 8 à 12 µg/minute (pour 70 kg) ; titration par paliers de 0,05 à 0,1 µg/kg/minute ; entretien moyen 2 à 4 µg/minute ; jusqu’à 30 µg/minute en cas de choc réfractaire","id":"noradrenaline-iv-adulte-perfusion","indication":"perfusion intraveineuse continue par pompe (hypotension)","intervalle":"pression contrôlée toutes les 2 minutes jusqu’à la cible, puis toutes les 5 minutes ; pas d’arrêt brusque","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte (non recommandé chez l’enfant)","produit_ch":"Noradrenalin Sintetica 0,06 mg/ml, 0,10 mg/ml, 0,12 mg/ml, 0,20 mg/ml (Swissmedic 67023)","substance":"noradrénaline","titulaire":"Sintetica SA, 6850 Mendrisio","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=67023&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/a562ef5864464d58bf5b717cfe0930ae-fr.html","voie":"IV continue par cathéter veineux"},"oxazepam-po-adulte-sevrage-alcool":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"La posologie doit être adaptée à la sensibilité individuelle de chaque patient. Choisir la posologie efficace la plus faible et la durée de traitement la plus brève possible.\nLe risque de symptômes de sevrage ainsi que de phénomènes de rebond est augmenté lors de l'arrêt brusque du traitement. Par conséquent, l'interruption du traitement par Seresta/Seresta forte doit avoir lieu de façon graduelle (voir «Mises en garde et précautions»).\nChez les alcooliques présentant des manifestations aiguës de sevrage telles que tremblements et états anxieux: 15-30 mg, 3-4 fois par jour.\nPosologie chez les patients âgés: Au début du traitement, 15 mg 1-2 fois par jour; la dose quotidienne totale peut si nécessaire aller jusqu'à 45-60 mg.\nDurée du traitement\nLa durée du traitement doit être aussi brève que possible et ne devrait généralement pas dépasser 2-3 mois.\nEn cas de thérapie de longue durée, il est nécessaire d'évaluer régulièrement s'il est judicieux de poursuivre le traitement.\nLe traitement avec Seresta/Seresta forte ne devrait pas être interrompu brusquement en raison de possibles symptômes de sevrage; réduire progressivement la posologie."}],"aips_publie":"2026-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Juin 2026)","aips_version":"Juin 2026","dose":"15 à 30 mg 3 à 4 fois par jour","duree":"aussi brève que possible ; arrêt progressif","id":"oxazepam-po-adulte-sevrage-alcool","indication":"manifestations aiguës de sevrage alcoolique (tremblements, anxiété)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte ; patient âgé : 15 mg 1 à 2 fois par jour au début","produit_ch":"Seresta®/- forte, comprimés (Swissmedic 32497)","substance":"oxazépam","titulaire":"Viatris Pharma GmbH, 6312 Steinhausen","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=32497&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/4d80fb4a45624a25a2df5d68fc8eb23f-fr.html","voie":"PO"},"prednisone-po-adulte-aigu":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"La posologie initiale dépend de la maladie à traiter et correspond habituellement à 5-60 mg/jour; des doses nettement plus élevées sont toutefois autorisées et peuvent être inévitables à court terme dans les cas aigus ou particulièrement sévères nécessitant une amélioration rapide.\nLors de maladies aiguës ne compromettant pas le pronostic vital, la dose varie entre 15 et 30 mg/jour; des doses plus élevées peuvent être néanmoins nécessaires chez certains patients.\nComme pour toute thérapie par glucocorticoïdes, la thérapie par Prednisone Streuli, si elle dépasse 8 à 10 jours, ne devrait pas être interrompue subitement, mais terminée par une diminution lente et par paliers des doses journalières, afin d'éviter une récurrence aiguë de la maladie et une insuffisance surrénale (syndrome de sevrage aux glucocorticoïdes). L'adaptation de la posologie au rythme d'incrétion circadien doit être atteinte à la fin de cette diminution progressive."}],"aips_publie":"2026-06-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour en juin 2026) : posologie initiale habituelle 5–60 mg/j ; réduction progressive si le traitement dépasse quelques jours ; seuil de Cushing 7,5 mg","aips_version":"Juin 2026","dose":"15–30 mg/j","id":"prednisone-po-adulte-aigu","lu_le":"2026-10-17","lu_par":"Galien","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Contre-lecture indépendante par Asclépios en attente ; valide_par_vial non encore donné.","population":"adulte, maladie aiguë ne compromettant pas le pronostic vital","produit_ch":"Prednisone Streuli® comprimés sécables 5, 20 et 50 mg (Swissmedic 29349)","substance":"prednisone","titulaire":"Streuli Pharma SA, 8730 Uznach","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=29349&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/20fd4e0534634d9a939cba4c8509130b-fr.html","voie":"PO"},"tenecteplase-iv-adulte-avc":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Metalyse doit être administré le plus tôt possible, moins de 4,5 heures après le dernier état connu sans symptômes et après avoir exclu une hémorragie intracrânienne au moyen d'une imagerie appropriée. L'effet du traitement varie en fonction du temps, c'est pourquoi un traitement précoce augmente la probabilité d'un résultat favorable.\nLa dose de Metalyse est à ajuster en fonction du poids corporel et ne peut excéder une dose unique de 5000 unités (25 mg) de ténectéplase.\nLe volume nécessaire à l'administration de la dose correcte totale peut être déterminé au moyen du schéma suivant (tableau 1):\nTableau 1\nPoids corporel du patient (kg)\nTénectéplase\n(U)\nTénectéplase\n(mg)\nVolume correspondant de la solution reconstituée (ml)\n< 60\n3000\n15\n3.0\n≥60 à < 70\n3500\n17.5\n3.5\n≥70 à < 80\n4000\n20\n4.0\n≥80 à < 90\n4500\n22.5\n4.5\n≥90\n5000\n25\n5.0\nPatients âgés (> 80 ans)\nEn raison d'un risque hémorragique accru, Metalyse doit être utilisé avec prudence chez les patients âgés (> 80 ans) (voir également «Mises en garde et précautions»).\nEnfants et adolescents\nL'utilisation et la sécurité de Metalyse solution injectable chez les enfants et les adolescents de moins de 18 ans n'ont pas été étudiées jusqu'à présent.\nMode d'administration correct\nLa solution reconstituée doit être administrée par voie intraveineuse et est destinée à un usage immédiat.\nLa dose requise doit être administrée sous forme d'un bolus intraveineux unique, en l'espace de 5 à 10 secondes."}],"aips_publie":"2025-05-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Mai 2025)","aips_version":"Mai 2025","dose":"selon le poids : < 60 kg : 3000 U (15 mg) ; ≥ 60 à < 70 kg : 3500 U (17,5 mg) ; ≥ 70 à < 80 kg : 4000 U (20 mg) ; ≥ 80 à < 90 kg : 4500 U (22,5 mg) ; ≥ 90 kg : 5000 U (25 mg) ; maximum 5000 U (25 mg)","duree":"moins de 4,5 heures après le dernier état connu sans symptômes, hémorragie intracrânienne exclue par imagerie","id":"tenecteplase-iv-adulte-avc","indication":"accident vasculaire cérébral ischémique aigu (Metalyse 5000 U)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte (non étudié avant 18 ans) ; prudence après 80 ans","produit_ch":"Metalyse® 5000 U (Swissmedic 69958)","substance":"ténectéplase","titulaire":"Boehringer Ingelheim (Schweiz) GmbH, Bâle","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=69958&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/e5a4e02c117149bca0e1d43b271807c3-fr.html","voie":"IV, bolus unique en 5 à 10 secondes"},"tenecteplase-iv-adulte-infarctus":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Metalyse doit être administré le plus tôt possible après le début des symptômes.\nLa dose de Metalyse est à ajuster en fonction du poids corporel et ne peut excéder 10 000 U. Le volume nécessaire à l'administration de la dose correcte peut être déterminé au moyen du tableau 1 ci-dessous:\nTableau 1\nPoids corporel du patient (kg)\nTénectéplase\n(U)\nTénectéplase\n(mg)\nVolume de la solution prête à l'emploi (ml)\n< 60\n6 000\n30\n6\n≥ 60 à < 70\n7 000\n35\n7\n≥ 70 à < 80\n8 000\n40\n8\n≥ 80 à < 90\n9 000\n45\n9\n≥ 90\n10 000\n50\n10\nTraitement associé\nIl est recommandé d'administrer le traitement antithrombotique associé conformément aux recommandations thérapeutiques internationales pour la prise en charge de l'infarctus du myocarde avec élévation du segment ST.\nPatients âgés (≥75 ans)\nEn raison d'un risque hémorragique accru, la prudence est de rigueur lors de l'utilisation de Metalyse chez les patients âgés (≥75 ans) (voir également «Mises en garde et précautions»).\nEnfants et adolescents\nL'utilisation et la sécurité de Metalyse solution injectable chez les enfants et les adolescents de moins de 18 ans n'ont pas été étudiées jusqu'à présent.\nMode d'administration correct:\nLa solution reconstituée doit être administrée par voie intraveineuse et est destinée à un usage immédiat.\nLa dose requise doit être administrée sous forme d'un bolus intraveineux unique, en l'espace de 5 à 10 secondes."}],"aips_publie":"2025-10-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Octobre 2025)","aips_version":"Octobre 2025","dose":"selon le poids : < 60 kg : 6000 U (30 mg) ; ≥ 60 à < 70 kg : 7000 U (35 mg) ; ≥ 70 à < 80 kg : 8000 U (40 mg) ; ≥ 80 à < 90 kg : 9000 U (45 mg) ; ≥ 90 kg : 10 000 U (50 mg) ; maximum 10 000 U","id":"tenecteplase-iv-adulte-infarctus","indication":"infarctus du myocarde avec sus-décalage du segment ST (Metalyse 10 000 U)","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte (non étudié avant 18 ans) ; prudence à 75 ans ou plus","produit_ch":"Metalyse® 10’000 U (Swissmedic 55418)","substance":"ténectéplase","titulaire":"Boehringer Ingelheim (Schweiz) GmbH, Bâle","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=55418&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/dfe2a6bb0056470487dc1c16e8a8065e-fr.html","voie":"IV, bolus unique en 5 à 10 secondes"},"thiamine-iv-im-carence-severe":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Adultes et adolescents à partir de 12 ans\nLors d'hypovitaminose en thiamine sévère et d'avitaminose en thiamine (en cas de myocardiopathie d'origine alcoolique, d'encéphalopathie de Wernicke et de béribéri, par exemple), le traitement peut être instauré par voie parentérale (par voie i.m. ou, lentement, par voie i.v.) à raison de doses quotidiennes pouvant atteindre 200 mg, afin qu'un taux suffisant de thiamine soit rapidement obtenu dans le sang.\nJusqu'à présent, l'utilisation et l'innocuité de Benerva n'ont pas été systématiquement étudiées chez les enfants et les adolescents.\nInstructions spéciales pour la posologie\nDans les cas graves de carence en thiamine, il est recommandé d'avoir d'abord recours à la voie parentérale. Pour la poursuite du traitement, il convient, si possible, de choisir la voie orale.\nAmpoules: par principe, l'injection intraveineuse doit avoir lieu très lentement."}],"aips_publie":"2019-04-01","aips_rubrique":"Posologie/Mode d’emploi (information mise à jour : Avril 2019)","aips_version":"Avril 2019","dose":"jusqu’à 200 mg/j","id":"thiamine-iv-im-carence-severe","indication":"carence sévère en thiamine (encéphalopathie de Wernicke, béribéri, atteinte cardiaque d’origine alcoolique)","intervalle":"voie parentérale d’abord, relais oral dès que possible","lu_le":"2026-10-17","lu_par":"Pharmakon","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Ligne non validée : contre-lecture par Galien et accord de Vial en attente.","population":"adulte et adolescent dès 12 ans","produit_ch":"Benerva® (Swissmedic 10989)","substance":"thiamine (vitamine B1)","titulaire":"Farmaceutica Teofarma Suisse SA, 6901 Lugano","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=10989&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/4a4ad15088d74b119203e22f322ec56c-fr.html","voie":"IM ou IV lente"},"valaciclovir-po-adulte-zona":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Posologie usuelle:\nAdultes:\nTraitement du zona (y compris ophtalmique):\n1000 mg de Valtrex 3 fois par jour pendant 7 jours.\nTraitement du zona (zona ophtalmique inclus):\nClairance de la créatinine\nPosologie de Valtrex\n≥50 ml/minute\n1000 mg 3 fois par jour\n(aucun ajustement nécessaire)"},{"rubrique":"Indications/Possibilités d’emploi","texte":"Valtrex est indiqué pour le traitement du zona (entreprendre le traitement aussi rapidement que possible, au plus tard dans les 72 heures)."}],"aips_publie":"2025-12-01","aips_rubrique":"Posologie/Mode d’emploi, zona y compris zona ophtalmique (information mise à jour en décembre 2025)","aips_version":"Décembre 2025","dose":"1000 mg","duree":"7 jours, à débuter au plus tard dans les 72 heures suivant l’éruption","id":"valaciclovir-po-adulte-zona","intervalle":"3×/j","lu_le":"2026-10-17","lu_par":"Galien","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Contre-lecture indépendante par Asclépios en attente ; valide_par_vial non encore donné.","population":"adulte, clairance de la créatinine ≥ 50 ml/min","produit_ch":"Valtrex® comprimés pelliculés 250 mg et 500 mg (Swissmedic 53116)","substance":"valaciclovir","titulaire":"GlaxoSmithKline AG, 6340 Baar","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=53116&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/d1180e977490458dabfb3c4e73cc1719-fr.html","voie":"PO"},"valaciclovir-po-adulte-zona-ir":{"aips_extrait":[{"rubrique":"Posologie/Mode d’emploi","texte":"Posologie usuelle:\nAdultes:\nTraitement du zona (y compris ophtalmique):\n1000 mg de Valtrex 3 fois par jour pendant 7 jours.\nTraitement du zona (zona ophtalmique inclus):\nClairance de la créatinine\nPosologie de Valtrex\n≥50 ml/minute\n1000 mg 3 fois par jour\n(aucun ajustement nécessaire)\n30 à 49 ml/minute\n1000 mg 2 fois par jour\n10 à 29 ml/minute\n1000 mg 1 fois par jour\n<10 ml/minute\n500 mg 1 fois par jour"}],"aips_publie":"2025-12-01","aips_rubrique":"Posologie/Mode d’emploi, instructions posologiques particulières, insuffisance rénale (décembre 2025)","aips_version":"Décembre 2025","dose":"clairance 30–49 ml/min : 1000 mg 2×/j ; 10–29 ml/min : 1000 mg 1×/j ; < 10 ml/min : 500 mg 1×/j","duree":"7 jours","id":"valaciclovir-po-adulte-zona-ir","lu_le":"2026-10-17","lu_par":"Galien","methode":"Texte officiel AIPS publié par Refdata (téléchargement XML Swissmedic/Refdata du 17.10.2026, export autorisé par les conditions d’utilisation) ; rubrique copiée mot pour mot, ligne de dose dérivée et contrôlée à la main contre l’extrait.","note":"Contre-lecture indépendante par Asclépios en attente ; valide_par_vial non encore donné.","population":"adulte avec insuffisance rénale, zona","produit_ch":"Valtrex® comprimés pelliculés 250 mg et 500 mg (Swissmedic 53116)","substance":"valaciclovir","titulaire":"GlaxoSmithKline AG, 6340 Baar","url":"https://swissmedicinfo-pro.ch/showText.aspx?authNr=53116&lang=FR&supportMultipleResults=1&textType=FI","url_texte":"https://files.refdata.ch/simis-public-prod/MedicinalDocuments/d1180e977490458dabfb3c4e73cc1719-fr.html","voie":"PO"}};
